"Piedi alla larghezza delle anche, bilanciere sopra la metà del piede. Piegati prendendo il bilanciere appena fuori dalle gambe: tibie che lo toccano, schiena in posizione neutra (curve naturali), spalle leggermente davanti al bilanciere.": "Pies al ancho de la cadera, barra sobre la mitad del pie. Agáchate y agarra la barra justo por fuera de las piernas: tibias tocándola, espalda en posición neutra (curvas naturales), hombros un poco por delante de la barra.",
