"Piedi molto larghi con punte in fuori, presa stretta dentro le gambe, busto più verticale che nello stacco classico.": "Pies muy abiertos con las puntas hacia fuera, agarre estrecho por dentro de las piernas, tronco más vertical que en el peso muerto clásico.",
