"Prendo l ultimo carico che hai usato e ne calcolo l #%. E un riferimento pratico per le serie in cui vuoi restare a circa due ripetizioni dal cedimento: utile nelle giornate storte o nelle settimane di scarico. Formula: ultimo carico × #.": "Tomo la última carga que usaste y calculo el #%. Es una referencia práctica para las series en las que quieres quedarte a unas dos repeticiones del fallo: útil en los días malos o en las semanas de descarga. Fórmula: última carga × #.",
