"Sdraiato con occhi sotto il bilanciere. Cinque punti di contatto: testa, scapole e glutei sulla panca, piedi a terra. Scapole addotte e depresse (strette e portate verso il basso): creano una base stabile e proteggono la spalla.": "Tumbado con los ojos bajo la barra. Cinco puntos de contacto: cabeza, escápulas y glúteos en el banco, pies en el suelo. Escápulas en aducción y depresión (juntas y llevadas hacia abajo): crean una base estable y protegen el hombro.",
"Sdraiato sul fianco, corpo in linea, testa appoggiata sul braccio.": "Tumbado de lado, cuerpo alineado, cabeza apoyada en el brazo.",
"Sdraiato sulla panca, manubrio tenuto a due mani sopra il petto, gomiti leggermente flessi.": "Tumbado en el banco, mancuerna sujeta con las dos manos sobre el pecho, codos ligeramente flexionados.",
"Sdraiato, avvicina le scapole tra loro e abbassa le spalle.": "Tumbado, junta las escápulas y baja los hombros.",
"Sdraiato, bilanciere EZ o manubri sopra il petto, braccia leggermente inclinate verso la testa.": "Tumbado, barra EZ o mancuernas sobre el pecho, brazos ligeramente inclinados hacia la cabeza.",
"Sdraiato, manubri sopra il petto con palmi che si guardano, gomiti leggermente flessi e fissi.": "Tumbado, mancuernas sobre el pecho con las palmas enfrentadas, codos ligeramente flexionados y fijos.",
"Se con il silenzioso non senti nulla, affidati al lampeggio.": "Si en silencio no oyes nada, confía en el parpadeo.",
"Se la schiena si inarca, piega un po' le ginocchia.": "Si la espalda se arquea, flexiona un poco las rodillas.",
