"l’ultimo isolamento leggero da 15-20 ripetizioni": "el último aislamiento ligero de 15-20 repeticiones",
"isolamenti da 12-15 ripetizioni": "aislamientos de 12-15 repeticiones",
"spinte e tirate in superserie per risparmiare tempo": "empujes y tirones en superserie para ahorrar tiempo",
"Massa magra bassa per la tua altezza: più serie per la crescita, il muscolo viene prima.": "Masa magra baja para tu altura: más series para crecer, el músculo es lo primero.",
"Proteine: circa # g al giorno (# g per kg di massa magra).": "Proteínas: unos # g al día (# g por kg de masa magra).",
"Grasso sopra la media: si tengono i carichi per salvare il muscolo, il dispendio arriva da passi (8-10 mila) e cardio leggero.": "Grasa por encima de la media: se mantienen las cargas para salvar el músculo, el gasto llega de los pasos (8-10 mil) y cardio suave.",
"Massa magra in calo nell’ultima BIA: volume giù del 15% e carichi fermi finché risale.": "Masa magra en descenso en la última BIA: volumen −15% y cargas quietas hasta que suba.",
"pensato per il corpo libero": "pensado para peso corporal",
"massa magra da costruire": "masa magra que construir",
"Il coach ne prende spunto adesso": "El coach se inspira en él ahora",
"Da dove prende spunto il coach": "De dónde saca ideas el coach",
"Le schede più famose: il coach non le copia, ne prende le idee giuste per te": "Los planes más famosos: el coach no los copia, toma las ideas adecuadas para ti",
"Dettaglio": "Detalle",
"Preso da qui": "Tomado de aquí",
"Come ho costruito il tuo programma": "Cómo he construido tu programa",
"Ho messo insieme chi sei, cosa stai vivendo e i tuoi dati fisici. Le schede famose sono esempi: ne prendo le idee giuste per te.": "He juntado quién eres, lo que vives y tus datos físicos. Los planes famosos son ejemplos: tomo las ideas adecuadas para ti.",
"Rifai il programma per vedere da quali metodi prende spunto.": "Rehaz el programa para ver en qué métodos se inspira.",
"Il coach compone il programma con fattore fisico, psicologico e momento di vita.": "El coach compone el programa con factor físico, psicológico y momento vital.",
"Ripetizioni migliori": "Mejores repeticiones",
"1RM stimato": "1RM estimado",
"dalla prima seduta del grafico": "desde la primera sesión del gráfico",
"Primo punto: dalla prossima seduta vedi la linea.": "Primer punto: desde la próxima sesión verás la línea.",
"Dopo il primo allenamento il grafico parte da qui.": "Tras el primer entrenamiento el gráfico empieza aquí.",
"Primo punto: dal prossimo peso vedi la linea.": "Primer punto: desde el próximo peso verás la línea.",
