"volume": "volumen",
"allenamenti in 7 giorni: il riposo fa crescere.": "entrenamientos en 7 días: el descanso también te hace crecer.",
"Se il malessere dura, parlane con il medico.": "Si el malestar dura, háblalo con el médico.",
"Abitudine avviata.": "Hábito en marcha.",
"settimane di fila": "semanas seguidas",
