"media": "media",
"bassa": "baja",
"Dal tuo storico:": "Según tu historial:",
"Il livello dipende da quanto e come ti alleni: dopo qualche settimana il coach lo verifica sul tuo storico.": "El nivel depende de cuánto y cómo entrenas: tras unas semanas el coach lo verifica con tu historial.",
"Livello:": "Nivel:",
"Spingi via il pavimento con tutto il piede.": "Empuja el suelo con todo el pie.",
"Fianchi indietro come per chiudere una porta, poi spingili avanti.": "Cadera atrás como para cerrar una puerta, luego empújala adelante.",
"Allontana il peso da te, come per spingere via la panca.": "Aleja el peso de ti, como si empujaras el banco.",
"Spingi il peso verso il soffitto e passa con la testa sotto.": "Empuja el peso hacia el techo y pasa la cabeza por debajo.",
"Porta i gomiti verso i fianchi.": "Lleva los codos hacia la cadera.",
"Porta i gomiti verso le tasche.": "Lleva los codos hacia los bolsillos.",
"Senti il muscolo che lavora: discesa in 2–3 secondi.": "Siente el músculo trabajar: baja en 2–3 segundos.",
"Stessa ampiezza a ogni seduta: così i carichi sono confrontabili.": "Mismo recorrido en cada sesión: así las cargas se pueden comparar.",
"La tua posizione:": "Tu posición:",
"piedi alla larghezza delle anche": "pies al ancho de la cadera",
"piedi alla larghezza delle spalle": "pies al ancho de los hombros",
"piedi più larghi delle spalle, punte aperte": "pies más anchos que los hombros, puntas abiertas",
"Caviglia rigida: talloni su due dischi sottili.": "Tobillo rígido: talones sobre dos discos finos.",
"Non trattenere il fiato: espira mentre sollevi, inspira in discesa. Carichi moderati, 8–12 ripetizioni.": "No contengas la respiración: espira al subir, inspira al bajar. Cargas moderadas, 8–12 repeticiones.",
"Pensa a": "Piensa en",
"Cintura": "Cinturón",
"Solo serie pesanti": "Solo series pesadas",
"Test in due minuti": "Tests de dos minutos",
"Il coach sceglie le varianti in base al tuo corpo: talloni rialzati, spinte inclinate, larghezza dello squat.": "El coach elige las variantes según tu cuerpo: talones elevados, empujes inclinados, anchura de sentadilla.",
"Femorali: squat e hip thrust non li fanno crescere, serve la flessione del ginocchio (leg curl).": "Isquiotibiales: sentadilla y hip thrust no los hacen crecer, hace falta flexión de rodilla (curl femoral).",
"Retto femorale: cresce solo con la leg extension, schienale un po’ reclinato.": "Recto femoral: solo crece con la extensión de piernas, respaldo algo reclinado.",
"Spalle larghe: la panca copre il deltoide anteriore, le alzate laterali quello laterale.": "Hombros anchos: el press de banca cubre el deltoides anterior, las elevaciones laterales el lateral.",
"Bicipite: un curl su panca inclinata e uno alla Scott per crescere in tutta la lunghezza.": "Bíceps: un curl en banco inclinado y uno Scott para crecer en toda su longitud.",
"Caviglia: ginocchio al muro": "Tobillo: rodilla a la pared",
"Alluce a 12 cm dal muro, tallone a terra: il ginocchio tocca il muro?": "Dedo gordo a 12 cm de la pared, talón en el suelo: ¿la rodilla toca la pared?",
"Tocca": "Toca",
"Non tocca": "No toca",
"Spalle: braccia al muro": "Hombros: brazos en la pared",
"Schiena e braccia al muro, porta le braccia in alto senza staccarle: ci riesci?": "Espalda y brazos en la pared, sube los brazos sin despegarlos: ¿lo consigues?",
"Squat: la tua larghezza": "Sentadilla: tu anchura",
"Prova tre larghezze a corpo libero: tieni quella dove scendi di più senza fastidi.": "Prueba tres anchuras sin peso: quédate con la que bajas más sin molestias.",
"Stretta": "Estrecha",
"Media": "Media",
"Larga": "Ancha",
"Spalle: spinte con presa stretta o manubri a presa neutra, ampiezza senza dolore. Si torna al pieno quando il fastidio cala.": "Hombros: empujes con agarre estrecho o mancuernas en agarre neutro, recorrido sin dolor. Se vuelve al completo cuando baja la molestia.",
"Ginocchia: prima delle gambe leg extension isometrica 5 × 45 s (dolore fino a 3/10), discesa in 3–4 s, profondità senza dolore.": "Rodillas: antes de piernas, extensión isométrica 5 × 45 s (dolor hasta 3/10), bajada en 3–4 s, profundidad sin dolor.",
"Schiena bassa: riscaldamento McGill (curl-up, plank laterale, bird dog), tenute di 8-6-4 secondi.": "Zona lumbar: calentamiento McGill (curl-up, plancha lateral, bird dog), mantenimientos de 8-6-4 segundos.",
