"Fatica accumulata: le prossime # sedute sono di scarico (serie -#%, carico -#%) per ricaricare le energie.": "Fatiga acumulada: las próximas # sesiones son de descarga (series -#%, carga -#%) para recargar energías.",
"Prontezza bassa da giorni e altri segnali di recupero scarso: le prossime # sedute sono di scarico": "Disposición baja desde hace días y otras señales de recuperación escasa: las próximas # sesiones son de descarga",
