"Stanchezza che non passa": "Cansancio que no pasa",
"Ho capito": "Entendido",
"La stanchezza dura da due settimane: questa settimana riposa o fai solo camminate.": "El cansancio dura desde hace dos semanas: esta semana descansa o haz solo caminatas.",
"Il coach ha dovuto alleggerire il programma due volte in poco tempo: questa settimana riposa o fai solo camminate.": "El coach ha tenido que aligerar el programa dos veces en poco tiempo: esta semana descansa o haz solo caminatas.",
"Se non passa, dormi male o ti senti giù, parlane con il medico: l’app non può capire cosa c’è dietro.": "Si no pasa, duermes mal o te sientes decaído, habla con tu médico: la app no puede saber qué hay detrás.",
